const resp = $('Customise resume').item.json;
// adjust this path to wherever the text sits in your OpenAI node's output
const text = $('Customise resume').item.json.output[0].content[0].text;
const fields = JSON.parse(text.replace(/```json|```/g, '').trim());

return {
  json: {
    docId: $json.id,
    requests: Object.entries(fields).map(([key, value]) => ({
      replaceAllText: {
        containsText: { text: `{{${key}}}`, matchCase: true },
        replaceText: String(value)
      }
    }))
  }
};
